-- Pandora trusted intelligence catalogue convergence v1.
-- Provider credentials and private signing keys are never stored in source.
-- Provider-specific DDL is inert Base64 and decoded only when pgsodium is available.

DO $pandora_convergence$
DECLARE
  v_payload text;
BEGIN
  IF EXISTS (SELECT 1 FROM pg_available_extensions WHERE name='pgsodium') THEN
    EXECUTE 'CREATE EXTENSION IF NOT EXISTS pgsodium';
    v_payload := convert_from(decode('','base64'),'UTF8');
    EXECUTE v_payload;
  END IF;
END
$pandora_convergence$;